// =====================================================================
// Parse a one-word reply from the digest.
//
//   "done 42"   -> banks the win, marks the action complete
//   "skip 42"   -> dismisses it, never shown again
//   "snooze 42" -> back to open, resurfaces in a future digest
//
// Deliberately forgiving: case, punctuation and the word "ref"/"#" are
// all ignored. On a phone, one-handed, with a baby in the other arm,
// the parser should not be the hard part.
// =====================================================================

const msg = $input.first().json.message || {};
const text = String(msg.text || '').trim().toLowerCase();

const match = text.match(/^(done|skip|dismiss|snooze|no)\s*(?:ref)?\s*#?\s*(\d+)$/);

if (!match) {
  return [{ json: { understood: false, echo: text } }];
}

const verbRaw = match[1];
const actionId = parseInt(match[2], 10);

const verb =
  verbRaw === 'done'                              ? 'done'   :
  (verbRaw === 'skip' || verbRaw === 'dismiss' || verbRaw === 'no') ? 'dismissed' :
  'open';

return [{
  json: {
    understood: true,
    verb,
    action_id: actionId,
    chat_id: msg.chat && msg.chat.id,
  }
}];
